export function validateProviderContract(c={}){if(!c.providerId||!c.operationId)throw new Error('PROVIDER_CONTRACT_ID_REQUIRED');if(!c.truthClass)throw new Error('PROVIDER_CONTRACT_TRUTH_REQUIRED');if(!c.rights)throw new Error('PROVIDER_CONTRACT_RIGHTS_REQUIRED');if(!c.freshnessMs&&!c.staticDataset)throw new Error('PROVIDER_CONTRACT_FRESHNESS_REQUIRED');return {...c,enabled:c.enabled!==false}}
export function normalizeProviderEnvelope({contract,observedAt=null,issuedAt=null,receivedAt=new Date().toISOString(),records=[],sourceNative=null,quality='LIVE'}={}){const c=validateProviderContract(contract);return {providerId:c.providerId,operationId:c.operationId,truthClass:c.truthClass,observedAt,issuedAt,receivedAt,quality,records:Array.isArray(records)?records:[],sourceNative,rights:c.rights,provenance:{contractVersion:c.version??'unversioned'}}}
export function contractCaptureRequired(c={}){return !c.endpointVerified||!c.schemaHash||!c.rightsReviewed}
